const fmtMinutes=(n:number)=>n>=60?`${Math.floor(n/60)}h ${n%60?`${n%60}m`:''}`.trim():`${n}m`;

function Badge({children,tone='muted'}:{children:ReactNode;tone?:string}) {return <span className={`badge badge-${tone}`}>{children}</span>}
function IconBox({children,color='mint',small=false}:{children:ReactNode;color?:string;small?:boolean}) {return <div className={classNames('icon-box',`icon-${color}`,small&&'icon-sm')}>{children}</div>}
function SectionHead({eyebrow,title,sub,action}:{eyebrow?:string;title:string;sub?:string;action?:ReactNode}){return <div className="section-head"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>}
function EmptyState({icon,heading,body,action}:{icon:ReactNode;heading:string;body:string;action?:ReactNode}){return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{heading}</h3><p>{body}</p>{action}</div>}
function Progress({value,variant='mint'}:{value:number;variant?:string}){return <div className="progress-track"><div className={`progress-value progress-${variant}`} style={{width:`${Math.max(0,Math.min(100,value))}%`}} /></div>}
function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){return <label className="field"><span className="field-label">{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
