type Shared = {
  nav:(id:Route)=>void;
  sources:Source[];setSources:(v:Source[]|((p:Source[])=>Source[]))=>void;
  sessions:StudySession[];setSessions:(v:StudySession[]|((p:StudySession[])=>StudySession[]))=>void;
  goals:Goal[];setGoals:(v:Goal[]|((p:Goal[])=>Goal[]))=>void;
  completed:string[];toggle:(id:string)=>void;
  journal:JournalEntry[];setJournal:(v:JournalEntry[]|((p:JournalEntry[])=>JournalEntry[]))=>void;
  notes:string;setNotes:(v:string|((p:string)=>string))=>void;
  prefs:{name:string;audioFirst:boolean;reminders:boolean;timezone:string;dailyGoal:number;focusMinutes:number};
  setPrefs:(v:Shared['prefs']|((p:Shared['prefs'])=>Shared['prefs']))=>void;
  readerFile:string|null;setReaderFile:(v:string|null)=>void;readerName:string;setReaderName:(v:string)=>void;
  notify:(message:string)=>void;
};

function SearchPalette({close,nav,navGroups,sources}:{close:()=>void;nav:(r:Route)=>void;navGroups:{label:string;items:{id:Route;label:string;icon:ReactNode}[]}[];sources:Source[]}) {
  const [q,setQ]=useState('');
  useEffect(()=>{const h=(e:KeyboardEvent)=>{if(e.key==='Escape')close()};window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h)},[close]);
  const matches=navGroups.flatMap(g=>g.items).filter(r=>r.label.toLowerCase().includes(q.toLowerCase()));
  const matchingSources=sources.filter(s=>s.name.toLowerCase().includes(q.toLowerCase()));
  return <div className="modal-backdrop" onClick={close}><div className="command-modal" onClick={e=>e.stopPropagation()}><div className="command-input"><Search size={20}/><input autoFocus placeholder="Search pages and learning resources..." value={q} onChange={e=>setQ(e.target.value)}/><kbd>ESC</kbd></div><div className="command-results"><small>WORKSPACE</small>{matches.map(r=><button key={r.id} onClick={()=>nav(r.id)}>{r.icon}<span>{r.label}</span><ArrowRight size={14}/></button>)}{matchingSources.length>0&&<><small>YOUR SOURCES</small>{matchingSources.map(s=><button key={s.id} onClick={()=>nav('library')}><Library size={18}/><span>{s.name}</span><ArrowRight size={14}/></button>)}</>}{matches.length===0&&matchingSources.length===0&&<p className="no-results">No matches found.</p>}</div></div></div>
}

function Heading({eyebrow,title,description,actions}:{eyebrow?:string;title:string;description:string;actions?:ReactNode}){return <div className="page-heading"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{description}</p></div>{actions&&<div className="heading-actions">{actions}</div>}</div>}

